    public static function svg(string $name, string $class = "icon"): string
    {
        if (!isset(self::PATHS[$name])) {
            throw new InvalidArgumentException("Neznámá ikona „{$name}“.");
        }

        return "<svg class=\"" . htmlspecialchars($class, ENT_QUOTES | ENT_HTML5, "UTF-8") . "\" viewBox=\"0 0 24 24\" width=\"24\" height=\"24\" fill=\"none\" stroke=\"currentColor\""
            . " stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\" focusable=\"false\">"
            . self::PATHS[$name] . "</svg>";
    }
